use super::*;
use std::path::Path;
struct Source(&'static str);impl dm_preprocess::SourceProvider for Source{fn read(&self,_:&Path)->Result<String,String>{Ok(self.0.into())}}
fn engine()->EngineSnapshot{EngineSnapshot::from_bytes(include_bytes!("../../../fixtures/native_template.bin"),1).unwrap()}
fn front(text:&'static str,host:&Arc<dyn dm_tree::frontend::SettingExpressionQueries>,executor:&dm_exec::BuildExecutor,engine:&EngineSnapshot)->ColdFrontend{let seed=engine.frontend_seed();dm_tree::frontend::build_with_executor_and_semantic_state_for_policy_checked(Path::new("original-abi-scalar.dme"),&Source(text),&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(&seed),observer:None},None,executor,None,true,host).unwrap()}
#[test]
fn actual_original_abi_wave_uses_global_and_procedure_static_roots_without_driver_reparse_matches_legacy_and_recovers_after_cancel(){
 let engine=engine();let db=Arc::new(crate::query_db::QueryDb::default());let host=db.clone() as Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let executor=dm_exec::BuildExecutor::new(1).unwrap();let frontend=front("var/const/base=1+2\nvar/const/next=base+1\n/proc/p()\n    set waitfor=local_flag\n    var/const/local_flag=next-4\n    return next\n",&host,&executor,&engine);let bodies=dm_tree::frontend::BodyArena::new_typed(&frontend,dm_codegen_byond::typed_statements_supported_for_capture);let startup=crate::startup::capture_original_with_executor_and_bodies_checked(&frontend,&[],&executor,&bodies).unwrap();
 let old=crate::driver_facts::prepare_pinned_source_abi_with_startup_on_executor(&frontend,&engine,frontend.snapshot.tree.as_ref(),&startup,None,&executor).unwrap();assert!(old.prepared.diagnostics.is_empty(),"{:?}",old.prepared.diagnostics);
 let input_context=frontend.original_issued_initializer_context(startup.issued_initializer_plan()).unwrap();let ordinal=startup.plan().writes.iter().position(|write|matches!(write.target,dm_ir::InitializerTarget::ProcedureStatic(id)if id.name==SymbolId::of("local_flag"))).unwrap();let input=input_context.input(ordinal).unwrap();let root=input.expression().unwrap();
 let before=executor.install(||SCALAR_TEXT_PARSES.with(|n|n.get()));
 let native=executor.install(||crate::driver_facts::prepare_original_source_abi_with_startup_on_executor(&frontend,&engine,frontend.snapshot.tree.as_ref(),&startup,None,&executor)).unwrap();assert!(native.prepared.diagnostics.is_empty(),"{:?}",native.prepared.diagnostics);assert_eq!(native.policy_identity,old.policy_identity);assert_eq!(native.prepared.units().len(),old.prepared.units().len());
 for((old_member,old),(native_member,native))in old.prepared.units().iter().zip(native.prepared.units()){assert_eq!(old_member,native_member);assert_eq!(old.canonical_metadata(),native.canonical_metadata());}
 assert_eq!(executor.install(||SCALAR_TEXT_PARSES.with(|n|n.get())),before,"actual ABI source closure cannot render/reparse recursive static/global expressions");assert!(root.same_root(&input.expression().unwrap()));
 let warm=executor.install(||crate::driver_facts::prepare_original_source_abi_with_startup_on_executor(&frontend,&engine,frontend.snapshot.tree.as_ref(),&startup,None,&executor)).unwrap();assert_eq!(warm.prepared.units()[0].1.canonical_metadata(),native.prepared.units()[0].1.canonical_metadata());assert_eq!(executor.install(||SCALAR_TEXT_PARSES.with(|n|n.get())),before);
 let token=crate::daemon::control::Cancellation::default();let binding=crate::daemon::control::bind_with_deadline(token.clone(),std::time::Instant::now()+std::time::Duration::from_secs(300));token.cancel();let error=crate::driver_facts::prepare_original_source_abi_with_startup_on_executor(&frontend,&engine,frontend.snapshot.tree.as_ref(),&startup,None,&executor).err().expect("actual ABI operation");assert_eq!(error.operational_error().unwrap().kind(),std::io::ErrorKind::Interrupted);drop(binding);assert!(crate::driver_facts::prepare_original_source_abi_with_startup_on_executor(&frontend,&engine,frontend.snapshot.tree.as_ref(),&startup,None,&executor).is_ok());assert_eq!(db.db().stats(dm_query::Kind(4)).computed,0);
}
#[test]
fn original_abi_source_preserves_existing_late_invalid_constant_diagnostic_instead_of_eager_rejection(){
 let engine=engine();let db=Arc::new(crate::query_db::QueryDb::default());let host=db.clone() as Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let executor=dm_exec::BuildExecutor::new(1).unwrap();let frontend=front("var/const/gate=1+\n/proc/p()\n    set waitfor=gate\n    return\n",&host,&executor,&engine);let bodies=dm_tree::frontend::BodyArena::new_typed(&frontend,dm_codegen_byond::typed_statements_supported_for_capture);let startup=crate::startup::capture_original_with_executor_and_bodies_checked(&frontend,&[],&executor,&bodies).unwrap();
 let old=crate::driver_facts::prepare_pinned_source_abi_with_startup_on_executor(&frontend,&engine,frontend.snapshot.tree.as_ref(),&startup,None,&executor).unwrap();let native=crate::driver_facts::prepare_original_source_abi_with_startup_on_executor(&frontend,&engine,frontend.snapshot.tree.as_ref(),&startup,None,&executor).unwrap();assert!(!old.prepared.diagnostics.is_empty());assert_eq!(old.prepared.diagnostics.len(),native.prepared.diagnostics.len());for((old_row,old),(new_row,new))in old.prepared.diagnostics.iter().zip(&native.prepared.diagnostics){assert_eq!(old_row,new_row);assert_eq!(old.kind,new.kind);assert_eq!(old.message,new.message);}assert_eq!(old.prepared.units().len(),native.prepared.units().len());
}

#[test]
fn retained_original_abi_rejects_legacy_rows_then_reuses_current_source_units_without_scalar_reparse(){
 let owner=crate::runner_host::EnginePayload::capture(include_bytes!("../../../fixtures/native_template.bin").to_vec(),1,true,0).unwrap();let engine=&owner.snapshot;
 let db=Arc::new(crate::query_db::QueryDb::default());let host=db.clone() as Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let executor=dm_exec::BuildExecutor::new(1).unwrap();
 let frontend=front("var/const/base=1+2\n/proc/p()\n    set waitfor=flag\n    var/const/flag=base-3\n    return base\n",&host,&executor,engine);
 let bodies=dm_tree::frontend::BodyArena::new_typed(&frontend,dm_codegen_byond::typed_statements_supported_for_capture);let startup=crate::startup::capture_original_with_executor_and_bodies_checked(&frontend,&[],&executor,&bodies).unwrap();
 let store=crate::driver_facts::AbiArtifacts::with_engine_owner(owner.clone()).with_retained_shortcuts();
 let legacy=crate::driver_facts::prepare_pinned_source_abi_with_startup_on_executor_with_artifacts(&frontend,engine,frontend.snapshot.tree.as_ref(),&startup,None,&executor,Some(&store)).unwrap();assert!(legacy.prepared.diagnostics.is_empty());
 let before_counts=store.totals();let before=executor.install(||SCALAR_TEXT_PARSES.with(|n|n.get()));
 let call=||crate::driver_facts::prepare_original_source_abi_with_startup_on_executor_with_artifacts(&frontend,engine,frontend.snapshot.tree.as_ref(),&startup,None,&executor,Some(&store));
 let cold=executor.install(call).unwrap();assert!(cold.prepared.diagnostics.is_empty());assert!(store.totals().1>before_counts.1,"legacy semantic rows have no successful original producer witness");let counts=store.totals();
 let warm=executor.install(call).unwrap();assert_eq!(store.totals().1,counts.1);assert!(store.totals().0>counts.0,"real same-store source unit hit");assert_eq!(cold.prepared.units().len(),warm.prepared.units().len());
 for((old_member,old),(new_member,new))in cold.prepared.units().iter().zip(warm.prepared.units()){assert_eq!(old_member,new_member);assert!(Arc::ptr_eq(&old.inputs,&new.inputs));assert!(Arc::ptr_eq(old.abi.as_ref().unwrap(),new.abi.as_ref().unwrap()));assert_eq!(old.canonical_metadata(),new.canonical_metadata());}
 assert_eq!(executor.install(||SCALAR_TEXT_PARSES.with(|n|n.get())),before);assert_eq!(store.batch_reused(),0,"legacy batch shortcut cannot bypass source evidence");assert_eq!(store.scheduled_reused(),0);
 let token=crate::daemon::control::Cancellation::default();let binding=crate::daemon::control::bind_with_deadline(token.clone(),std::time::Instant::now()+std::time::Duration::from_secs(300));token.cancel();let counts=store.totals();let error=call().err().expect("cancelled warm source ABI");assert_eq!(error.operational_error().unwrap().kind(),std::io::ErrorKind::Interrupted);assert_eq!(store.totals(),counts);drop(binding);assert!(call().is_ok());assert_eq!(db.db().stats(dm_query::Kind(4)).computed,0);
}

#[test]
fn rebuilt_request_original_abi_reissues_only_produced_roots_and_preserves_real_unit_hits(){
 const TEXT:&str="var/const/base=1+2\nvar/const/next=base+1\n/datum/probe\n/proc/p()\n    set waitfor=flag\n    var/const/flag=next-4\n    return next\n/proc/q() as /datum/probe\n    return null\n";
 let engine=crate::runner_host::EnginePayload::capture(include_bytes!("../../../fixtures/native_template.bin").to_vec(),1,true,0).unwrap();let db=Arc::new(crate::query_db::QueryDb::default());let host=db.clone() as Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let executor=dm_exec::BuildExecutor::new(1).unwrap();let mut state=dm_tree::frontend::RetainedSemanticTree::new();let startup_store=crate::startup::StartupArtifacts::default();let store=crate::driver_facts::AbiArtifacts::with_engine_owner(engine.clone());
 let make=|state:&mut dm_tree::frontend::RetainedSemanticTree|{let seed=engine.snapshot.frontend_seed();dm_tree::frontend::build_with_executor_and_semantic_state_for_policy_checked(Path::new("rebuilt-original-abi.dme"),&Source(TEXT),&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(&seed),observer:None},None,&executor,Some(state),true,&host).unwrap()};
 let first=make(&mut state);let old_syntax=Arc::downgrade(&first.syntax);let arena=dm_tree::frontend::BodyArena::new_typed(&first,dm_codegen_byond::typed_statements_supported_for_capture);let startup=crate::startup::capture_original_with_artifacts_checked(&first,&[],&executor,&arena,&startup_store).unwrap();let before=executor.install(||SCALAR_TEXT_PARSES.with(|n|n.get()));
 let cold=executor.install(||crate::driver_facts::prepare_original_source_abi_with_startup_on_executor_with_artifacts(&first,&engine.snapshot,first.snapshot.tree.as_ref(),&startup,None,&executor,Some(&store))).unwrap();assert!(cold.prepared.diagnostics.is_empty(),"{:?}",cold.prepared.diagnostics);let counts=store.totals();assert!(counts.1>0);drop(startup);drop(arena);drop(first);
 let current=make(&mut state);assert!(!old_syntax.ptr_eq(&Arc::downgrade(&current.syntax)),"actual rebuilt composite frontend is distinct");let arena=dm_tree::frontend::BodyArena::new_typed(&current,dm_codegen_byond::typed_statements_supported_for_capture);let startup=crate::startup::capture_original_with_artifacts_checked(&current,&[],&executor,&arena,&startup_store).unwrap();let warm=executor.install(||crate::driver_facts::prepare_original_source_abi_with_startup_on_executor_with_artifacts(&current,&engine.snapshot,current.snapshot.tree.as_ref(),&startup,None,&executor,Some(&store))).unwrap();assert!(warm.prepared.diagnostics.is_empty(),"{:?}",warm.prepared.diagnostics);assert_eq!(store.totals().1,counts.1,"rebuilt wrapper cannot force cold ABI when actual original roots survive");assert!(store.totals().0>counts.0);
 for((old_id,old),(new_id,new))in cold.prepared.units().iter().zip(warm.prepared.units()){assert_eq!(old_id,new_id);assert!(Arc::ptr_eq(&old.inputs,&new.inputs));assert!(Arc::ptr_eq(old.abi.as_ref().unwrap(),new.abi.as_ref().unwrap()));}
 assert_eq!(executor.install(||SCALAR_TEXT_PARSES.with(|n|n.get())),before);assert_eq!(db.db().stats(dm_query::Kind(4)).computed,0);
}

#[test]
fn original_abi_produced_root_roster_quota_is_operational_uncached_and_same_request_recovers(){
 let owner=crate::runner_host::EnginePayload::capture(include_bytes!("../../../fixtures/native_template.bin").to_vec(),1,true,0).unwrap();let engine=&owner.snapshot;let db=Arc::new(crate::query_db::QueryDb::default());let host=db.clone() as Arc<dyn dm_tree::frontend::SettingExpressionQueries>;let executor=dm_exec::BuildExecutor::new(1).unwrap();let frontend=front("/proc/p()\n    set waitfor=0\n    return\n",&host,&executor,engine);let arena=dm_tree::frontend::BodyArena::new_typed(&frontend,dm_codegen_byond::typed_statements_supported_for_capture);let startup=crate::startup::capture_original_with_executor_and_bodies_checked(&frontend,&[],&executor,&arena).unwrap();
 // Warm the real canonical setting slot before isolating the NEW roster's charge.
 let body=&frontend.bodies[0];let metadata=frontend.snapshot.tree.member(body.member).unwrap().metadata.procedure.as_deref().unwrap();let dm_ir::ProcedureSettingNode::Setting(setting)=&metadata.settings[0]else{panic!("actual setting")};let root=frontend.setting_expression(body,metadata,&setting.value).unwrap();
 let counter=crate::query_db::body_syntax_counter_for_test(&db);let budget=crate::query_db::body_syntax_budget_for_test();let used=counter.load(std::sync::atomic::Ordering::Acquire);assert!(used<budget);let healthy=||Ok(());let admission=dm_syntax::SettingAdmission::new(counter,budget,&healthy);let held=admission.reserve(budget-used).unwrap();let store=crate::driver_facts::AbiArtifacts::with_engine_owner(owner.clone());
 let call=||crate::driver_facts::prepare_original_source_abi_with_startup_on_executor_with_artifacts(&frontend,engine,frontend.snapshot.tree.as_ref(),&startup,None,&executor,Some(&store));let error=call().err().expect("actual produced-root roster cannot allocate under exhausted SAME counter");assert_eq!(error.operational_error().unwrap().kind(),std::io::ErrorKind::OutOfMemory);
 let mut source_rows=0;store.visit_storage(|view|{if let dm_session::ObservedArtifactStorageView::Entry{value,..}=view{if let crate::driver_facts::abi_artifacts::Artifact::Unit(unit)=value.as_ref(){source_rows+=usize::from(unit.source.is_some());}}});assert_eq!(source_rows,0,"quota failure never publishes successful source witness/ABI row");drop(held);
 let cold=call().unwrap();assert!(cold.prepared.diagnostics.is_empty());let charged=counter.load(std::sync::atomic::Ordering::Acquire);assert!(charged>used,"actual retained root questions and Weak backing are admitted");let counts=store.totals();let warm=call().unwrap();assert!(warm.prepared.diagnostics.is_empty());assert_eq!(store.totals().1,counts.1);assert!(store.totals().0>counts.0);assert_eq!(counter.load(std::sync::atomic::Ordering::Acquire),charged,"warm source proof creates no new retained root roster");assert!(root.is_retained_in(&admission));assert_eq!(db.db().stats(dm_query::Kind(4)).computed,0);
}
